// Single source for type generation — used by `pnpm generate` and by test/generated.test.ts.
import openapiTS, { astToString } from "openapi-typescript";
import ts from "typescript";

export const CONTRACT = new URL("../../contracts/openapi.yaml", import.meta.url);
export const OUTPUT = new URL("../src/generated/schema.ts", import.meta.url);

const BANNER = `/**
 * This file was auto-generated by openapi-typescript (packages/api-client/scripts/schema.mjs).
 * Do not make direct changes to the file — run \`pnpm --filter @payproof/api-client generate\`.
 */

`;
const BLOB = ts.factory.createTypeReferenceNode("Blob");

export async function generateSchema() {
  const ast = await openapiTS(CONTRACT, {
    // multipart file fields (`contentEncoding: binary`) are uploaded as Blob/File, not string
    transform(schema) {
      if (schema.contentEncoding === "binary" || schema.format === "binary") return BLOB;
      return undefined;
    },
  });
  return BANNER + astToString(ast);
}
